//! Reader for `fixtures/object-raster-asset-admission/oracle.txt` (generated by
//! tools/gen.js: baseline `extOf`/`mimeOf` run verbatim, Node crypto digests and
//! Node-zlib PNG bytes; see HANDOFF.md) plus the shared builders of the tests.
use super::sniff::Sniffed;
use super::{AdmissionDecision, AdmissionRequest, Refusal, MAX_ASSETS};
use crate::object_document::{AssetId, AssetInventory, AssetKind, AssetRecord, AssetSource};
use serde_json::Value;
use std::sync::Arc;

/// The accepted SHA-256 as the digest port. The kernel sits in the document
/// layer and cannot import `request_receipts`; the owner transaction (L06-H)
/// passes `&sha256` the same way.
pub(crate) fn content_digest(bytes: &[u8]) -> [u8; 32] {
    crate::request_receipts::sha256(bytes)
}

/// The decision with the accepted SHA-256 and the existing PNG validator.
#[cfg(feature = "reference_image_asset")]
pub(crate) fn decide_native(
    request: &AdmissionRequest<'_>,
    inventory: &AssetInventory,
) -> AdmissionDecision {
    let ports = super::AdmissionPorts {
        digest: &content_digest,
        png: &super::png_port::check_png,
    };
    super::decide(request, inventory, &ports)
}

pub(crate) const ORACLE: &str = include_str!("fixtures/object-raster-asset-admission/oracle.txt");

pub(crate) fn rows(kind: &str) -> Vec<Value> {
    ORACLE
        .lines()
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .map(|line| serde_json::from_str::<Value>(line).expect("oracle row is JSON"))
        .filter(|row| row["kind"] == kind)
        .collect()
}

pub(crate) fn unhex(text: &str) -> Vec<u8> {
    assert!(text.len() % 2 == 0, "odd hex length");
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex digit pair"))
        .collect()
}

pub(crate) fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

/// An embedded image record whose allocation is its own fresh `Arc`.
pub(crate) fn embedded_record(
    id: &str,
    name: &str,
    media_type: &str,
    bytes: Vec<u8>,
) -> Arc<AssetRecord> {
    let allocation = Arc::new(bytes);
    let limit = allocation.capacity();
    let source = AssetSource::admitted_embedded(media_type.to_string(), allocation, limit)
        .expect("embedded source");
    Arc::new(
        AssetRecord::new(
            AssetId::new(id.to_string()).expect("asset id"),
            name.to_string(),
            AssetKind::Image,
            source,
        )
        .expect("asset record"),
    )
}

pub(crate) fn inventory(records: Vec<Arc<AssetRecord>>) -> AssetInventory {
    AssetInventory::new(records, Vec::new(), MAX_ASSETS, 0).expect("inventory")
}

/// `signature + filler` with the PNG signature: sniffs as PNG, is no real image.
pub(crate) fn png_like(fill: u8, len: usize) -> Vec<u8> {
    let mut bytes = vec![0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A];
    bytes.resize(len, fill);
    bytes
}

fn riff(form: &[u8; 4]) -> Vec<u8> {
    let mut b = b"RIFF".to_vec();
    b.extend_from_slice(&[0x24, 0, 0, 0]);
    b.extend_from_slice(form);
    b.extend_from_slice(b"fmt ");
    b
}

fn ftyp(brand: &[u8; 4]) -> Vec<u8> {
    let mut b = vec![0, 0, 0, 0x18];
    b.extend_from_slice(b"ftyp");
    b.extend_from_slice(brand);
    b.extend_from_slice(&[0; 4]);
    b
}

pub(crate) fn bmp_with_dib(dib: u32) -> Vec<u8> {
    let mut b = b"BM".to_vec();
    b.extend_from_slice(&[0; 12]);
    b.extend_from_slice(&dib.to_le_bytes());
    b.extend_from_slice(&[0; 8]);
    b
}

/// One minimal header per recognised container: (media type, kind, bytes).
pub(crate) fn samples() -> Vec<(&'static str, AssetKind, Vec<u8>)> {
    let image = AssetKind::Image;
    let video = AssetKind::Video;
    let audio = AssetKind::Audio;
    vec![
        ("image/png", image, png_like(0, 16)),
        (
            "image/jpeg",
            image,
            vec![0xFF, 0xD8, 0xFF, 0xE0, 0, 0x10, b'J', b'F', b'I', b'F', 0],
        ),
        (
            "image/gif",
            image,
            b"GIF89a\x01\x00\x01\x00\x00\x00\x00".to_vec(),
        ),
        ("image/webp", image, riff(b"WEBP")),
        ("image/bmp", image, bmp_with_dib(40)),
        ("image/avif", image, ftyp(b"avif")),
        ("video/mp4", video, ftyp(b"isom")),
        ("video/quicktime", video, ftyp(b"qt  ")),
        (
            "video/webm",
            video,
            vec![0x1A, 0x45, 0xDF, 0xA3, 0x9F, 0x42, 0x86],
        ),
        ("audio/wav", audio, riff(b"WAVE")),
        ("audio/ogg", audio, b"OggS\x00\x02".to_vec()),
        ("audio/flac", audio, b"fLaC\x00\x00\x00\x22".to_vec()),
        (
            "audio/mpeg",
            audio,
            b"ID3\x03\x00\x00\x00\x00\x00\x00".to_vec(),
        ),
    ]
}

pub(crate) fn ftyp_with(brand: &[u8; 4]) -> Vec<u8> {
    ftyp(brand)
}

pub(crate) fn riff_with(form: &[u8; 4]) -> Vec<u8> {
    riff(form)
}

pub(crate) fn expect_sniffed(media_type: &'static str, kind: AssetKind) -> Sniffed {
    Sniffed { media_type, kind }
}

pub(crate) fn empty() -> AssetInventory {
    inventory(Vec::new())
}

pub(crate) fn req<'a>(
    id: &'a str,
    name: &'a str,
    declared: &'a str,
    bytes: &'a [u8],
) -> AdmissionRequest<'a> {
    AdmissionRequest {
        request_id: id,
        name,
        declared_media_type: declared,
        bytes,
    }
}

pub(crate) fn refused(decision: AdmissionDecision) -> Refusal {
    match decision {
        AdmissionDecision::Refused(refusal) => refusal,
        other => panic!("expected a refusal, got {other:?}"),
    }
}
